// Worker entry: Next.js (OpenNext) for HTTP, plus the background jobs on the same Worker.
// docs/decisions/0002-one-worker-per-environment.md

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as nextHandler } from "./.open-next/worker.js";
import { handleScoringBatch, type ScoringJob } from "./src/jobs/scoring";
import { syncEvents } from "./src/jobs/sync-events";

export default {
  fetch: nextHandler.fetch,

  // Tournament schedule sync. The live loop (every minute) is added in M2.
  async scheduled(controller, env, ctx) {
    console.log(`[ingest] cron "${controller.cron}" (${env.APP_ENV})`);
    ctx.waitUntil(syncEvents(env));
  },

  async queue(batch, env) {
    await handleScoringBatch(batch, env);
  },
} satisfies ExportedHandler<CloudflareEnv, ScoringJob>;
